create table if not exists supply_recovery_actions (id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,source_type text not null,source_id uuid not null,action_type text not null check(action_type in ('reorder','reroute','expedite','substitute','hold')),status text not null default 'proposed' check(status in ('proposed','approved','executed','rejected','cancelled')),reason_code text not null,evidence_hash text not null check(length(evidence_hash)=64),created_at timestamptz not null default now(),approved_at timestamptz,executed_at timestamptz,unique(business_id,source_type,source_id,action_type));
create table if not exists supply_recovery_outcomes (id bigint generated always as identity primary key,business_id uuid not null references businesses(id) on delete cascade,action_id uuid not null references supply_recovery_actions(id) on delete restrict,outcome_type text not null check(outcome_type in ('fulfilled','partially_fulfilled','failed','expired')),measured_quantity numeric(24,8),unit text,evidence_hash text not null check(length(evidence_hash)=64),recorded_at timestamptz not null default now());
create index if not exists idx_v23_actions_business on supply_recovery_actions(business_id,status,created_at desc);
create index if not exists idx_v23_outcomes_action on supply_recovery_outcomes(action_id,recorded_at desc);
alter table supply_recovery_actions enable row level security;
alter table supply_recovery_outcomes enable row level security;
create policy v23_actions_select on supply_recovery_actions for select using(is_member(business_id));
create policy v23_outcomes_select on supply_recovery_outcomes for select using(is_member(business_id));
create or replace function public.v23_hash_recovery_action(p_business_id uuid,p_source_type text,p_source_id uuid,p_action_type text,p_reason_code text,p_evidence_hash text) returns text language sql immutable as $$ select encode(digest(concat_ws('|',p_business_id::text,p_source_type,p_source_id::text,p_action_type,p_reason_code,lower(p_evidence_hash)),'sha256'),'hex') $$;
create or replace function public.v23_propose_recovery_action(p_business_id uuid,p_source_type text,p_source_id uuid,p_action_type text,p_reason_code text,p_evidence_hash text) returns uuid language plpgsql security definer set search_path=public as $$ declare x uuid; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if length(p_evidence_hash)<>64 or p_evidence_hash !~ '^[0-9a-fA-F]{64}$' then raise exception 'Invalid evidence hash'; end if; perform pg_advisory_xact_lock(hashtextextended('NABUUMA|SUPPLY_RECOVERY|V2.3',0)); select id into x from supply_recovery_actions where business_id=p_business_id and source_type=p_source_type and source_id=p_source_id and action_type=p_action_type for update; if x is not null then return x; end if; insert into supply_recovery_actions(business_id,source_type,source_id,action_type,reason_code,evidence_hash) values(p_business_id,p_source_type,p_source_id,p_action_type,p_reason_code,lower(p_evidence_hash)) returning id into x; return x; end; $$;
create or replace function public.v23_record_recovery_outcome(p_business_id uuid,p_action_id uuid,p_outcome_type text,p_measured_quantity numeric,p_unit text,p_evidence_hash text) returns bigint language plpgsql security definer set search_path=public as $$ declare x bigint; begin if not has_role(p_business_id,ARRAY['owner','manager']::member_role[]) then raise exception 'Manager authorization required'; end if; if not exists(select 1 from supply_recovery_actions where id=p_action_id and business_id=p_business_id) then raise exception 'Recovery action not found for tenant'; end if; if length(p_evidence_hash)<>64 or p_evidence_hash !~ '^[0-9a-fA-F]{64}$' then raise exception 'Invalid evidence hash'; end if; insert into supply_recovery_outcomes(business_id,action_id,outcome_type,measured_quantity,unit,evidence_hash) values(p_business_id,p_action_id,p_outcome_type,p_measured_quantity,p_unit,lower(p_evidence_hash)) returning id into x; return x; end; $$;
revoke all on function public.v23_hash_recovery_action(uuid,text,uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.v23_hash_recovery_action(uuid,text,uuid,text,text,text) to authenticated;
revoke all on function public.v23_propose_recovery_action(uuid,text,uuid,text,text,text) from public,anon,authenticated;
grant execute on function public.v23_propose_recovery_action(uuid,text,uuid,text,text,text) to authenticated;
revoke all on function public.v23_record_recovery_outcome(uuid,uuid,text,numeric,text,text) from public,anon,authenticated;
grant execute on function public.v23_record_recovery_outcome(uuid,uuid,text,numeric,text,text) to authenticated;